package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The stored sheets. A sheet never changed has no row and reads as starting on the real date. */
@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Sheet find(String id) {
        return new Sheet(id, today(id), archived(id), parent(id));
    }

    /** The sheet as it stood at the end of the date: the date stands in for its today, and it is archived only when it
     *  was archived while its today was on or before it. */
    public Sheet find(String id, LocalDate asOf) {
        if (asOf == null) {
            return find(id);
        }
        List<LocalDate> archivedOn = jdbc.query("SELECT archived_on FROM sheet_archived WHERE sheet_id = ?",
                (rs, n) -> rs.getObject(1, LocalDate.class), id);
        return new Sheet(id, asOf, !archivedOn.isEmpty() && AsOf.counts(archivedOn.get(0), asOf), parent(id));
    }

    /**
     * The sheet's today. Use this — never {@code LocalDate.now()} — for every decision or default
     * that depends on the date.
     */
    public LocalDate today(String id) {
        List<LocalDate> found = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                (rs, n) -> rs.getObject(1, LocalDate.class), id);
        return found.isEmpty() ? LocalDate.now() : found.get(0);
    }

    /** Whether a steward archived the sheet: an archived sheet refuses every change. */
    public boolean archived(String id) {
        Integer found = jdbc.queryForObject("SELECT COUNT(*) FROM sheet_archived WHERE sheet_id = ?", Integer.class, id);
        return found != null && found > 0;
    }

    /** Archives the sheet; false when it was already archived. */
    public boolean archive(String id, String by) {
        if (archived(id)) {
            return false;
        }
        jdbc.update("INSERT INTO sheet_archived (sheet_id, archived_by, archived_on) VALUES (?, ?, ?)", id, by, today(id));
        return true;
    }

    /** The sheet's parent sheet id as set now (the parent setting), or null when none. */
    public String parent(String id) {
        List<String> found = jdbc.queryForList("SELECT setting_value FROM setting WHERE sheet_id = ? AND setting_key = 'parent'",
                String.class, id);
        return found.isEmpty() || found.get(0) == null || found.get(0).isBlank() ? null : found.get(0);
    }

    /** The sheet the sheet was cloned from, or null when it was not cloned. */
    public String source(String id) {
        List<String> found = jdbc.queryForList("SELECT source_id FROM sheet_source WHERE sheet_id = ?", String.class, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Notes that the sheet was cloned from the source. */
    public void saveSource(String id, String source) {
        jdbc.update("MERGE INTO sheet_source (sheet_id, source_id) KEY (sheet_id) VALUES (?, ?)", id, source);
    }

    /** Notes that the sheet has been loaded: from then on it exists. */
    public void markLoaded(String id) {
        jdbc.update("MERGE INTO sheet_loaded (id) KEY (id) VALUES (?)", id);
    }

    /** Whether the sheet exists: it has been loaded, or has its own today. */
    public boolean exists(String id) {
        Integer found = jdbc.queryForObject("SELECT (SELECT COUNT(*) FROM sheet_loaded WHERE id = ?)"
                + " + (SELECT COUNT(*) FROM sheet WHERE id = ?)", Integer.class, id, id);
        return found != null && found > 0;
    }

    public void saveToday(String id, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", id, today);
    }
}
